#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-08-10

/**
 * Agent Read()-path integrity — the undocumented 4th activation path (#3313).
 *
 * A skill can be reached four ways. Three are linted: `user-invocable: true`
 * (slash command), `disable-model-invocation: false` (model auto-select), and a
 * `skills:` preload edge. The fourth is a literal
 *   Read("${CLAUDE_PLUGIN_ROOT}/skills/<x>/SKILL.md")
 * in an agent body, which bypasses the Skill tool entirely. #3221 CONVERTED 7
 * load-bearing preload edges into exactly these lines, so they are deliberate
 * and load-bearing — yet no gate counted them, so 8 skills read as unreachable
 * while working fine.
 *
 * WHY THIS TEST EXISTS
 *
 * Every one of those lines carried the comment "The `<x>` skill is slash-only,
 * so it cannot be preloaded." That is false in the most dangerous direction:
 * those skills are `user-invocable: false` AND `disable-model-invocation: true`,
 * so there is no slash form and the model cannot auto-select them either. The
 * Read IS the only path. An editor who "corrected" that comment — or dropped the
 * line as redundant with a slash command that does not exist — would silently
 * delete the sole route to 8 skills, with nothing failing.
 *
 * Two assertions, both cheap:
 *   1. No agent body claims a skill is "slash-only" while that skill is
 *      user-invocable: false. The wording that invites the deletion cannot return.
 *   2. Every skill named in an agent Read() line still exists on disk. A rename
 *      that misses these lines breaks the path silently, since nothing resolves
 *      the string.
 */

import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '../..');
const AGENTS = join(REPO, 'src/agents');
const SKILLS = join(REPO, 'src/skills');

const READ_RE = /Read\("\$\{CLAUDE_PLUGIN_ROOT\}\/skills\/([a-z0-9-]+)\/SKILL\.md"\)/g;

let failures = 0;
const fail = (m) => { console.error(`  [0;31mFAIL[0m ${m}`); failures++; };
const pass = (m) => console.log(`  [0;32mPASS[0m ${m}`);

function isUserInvocable(skill) {
  const p = join(SKILLS, skill, 'SKILL.md');
  if (!existsSync(p)) return null;
  return /^user-invocable:\s*true\s*$/m.test(readFileSync(p, 'utf8'));
}

console.log('Agent Read()-path integrity (#3313)');
console.log('===================================');

const agents = readdirSync(AGENTS).filter((f) => f.endsWith('.md') && !/^(README|INDEX|CONTRIBUTING)\.md$/.test(f));

let readLines = 0;
let liars = 0;
let missing = 0;

for (const file of agents) {
  const body = readFileSync(join(AGENTS, file), 'utf8');

  // Assertion 2: every Read() target resolves to a real skill.
  for (const m of body.matchAll(READ_RE)) {
    readLines++;
    const skill = m[1];
    if (!existsSync(join(SKILLS, skill, 'SKILL.md'))) {
      fail(`${file}: Read() targets a skill that does not exist: ${skill}`);
      missing++;
    }
  }

  // Assertion 1: no "slash-only" claim about a skill that has no slash form.
  if (!/slash-only/i.test(body)) continue;
  const named = [...body.matchAll(READ_RE)].map((m) => m[1]);
  for (const skill of new Set(named)) {
    const invocable = isUserInvocable(skill);
    if (invocable === false) {
      fail(
        `${file}: claims "slash-only" about \`${skill}\`, which is ` +
          `user-invocable: false — there is no slash form. That wording invites ` +
          `deleting the Read() line, which is the skill's ONLY load path.`
      );
      liars++;
    }
  }
}

if (readLines === 0) {
  fail('found ZERO agent Read() lines — the 4th activation path vanished, or this regex stopped matching');
} else {
  pass(`${readLines} agent Read() line(s) found (the 4th activation path is present)`);
}
if (missing === 0) pass('every Read() target resolves to an existing skill');
if (liars === 0) pass('no agent claims "slash-only" about a non-user-invocable skill');

console.log('');
if (failures > 0) {
  console.error(`FAILED: ${failures} problem(s)`);
  process.exit(1);
}
console.log('SUCCESS: agent Read() paths are present, resolvable, and truthfully documented');
